import numpy as np
from PIL import Image
from scipy import ndimage
im=np.asarray(Image.open('/app/target.png').convert('RGB'),dtype=np.float32)
p=np.array([[235,226,131],[216,208,126],[200,189,92],[182,172,97],[186,163,36],[151,161,69],[169,147,43],[151,123,28],[115,120,57],[137,112,38]],np.float32)
def lab(rgb):
 x=np.asarray(rgb,dtype=float)/255;x=np.where(x<=.04045,x/12.92,((x+.055)/1.055)**2.4);xyz=x@np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.072175],[.0193339,.119192,.9503041]]).T/np.array([.95047,1,1.08883]);e=216/24389;k=24389/27;f=np.where(xyz>e,np.cbrt(xyz),(k*xyz+16)/116);return np.stack([116*f[...,1]-16,500*(f[...,0]-f[...,1]),200*(f[...,1]-f[...,2])],-1)
def metrics(tgt,out):
 rgb=np.empty((*tgt.shape,3),np.float32);rgb[:]=[248,244,236]
 for i in range(10):rgb[out==i+1]=p[i]
 bt=ndimage.gaussian_filter(im,sigma=(4.5,4.5,0));bp=ndimage.gaussian_filter(rgb,sigma=(4.5,4.5,0));de=np.linalg.norm(lab(bt)-lab(bp),axis=2)
 mask=ndimage.binary_dilation((tgt>0)|(out>0),iterations=9)
 iou=((out>0)&(tgt>0)).sum()/((out>0)|(tgt>0)).sum();acc=np.mean(out[tgt>0]==tgt[tgt>0])
 return iou,acc,de[mask].mean(),np.percentile(de[mask],90)
for mode in ['rgb','lab']:
 if mode=='rgb': dd=np.linalg.norm(im[:,:,None]-p[None,None],axis=3)
 else: dd=np.linalg.norm(lab(im)[:,:,None]-lab(p)[None,None],axis=3)
 mind=dd.min(2);base=dd.argmin(2)+1;base[mind>(50 if mode=='rgb' else 25)]=0
 for er in [1,2,3]:
  masks=[]
  for k in range(1,11):masks.append(ndimage.distance_transform_edt(base==k)>er)
  for step in [4,5]:
   rad=4;disk=np.fromfunction(lambda y,x:(x-rad)**2+(y-rad)**2<=rad**2,(2*rad+1,2*rad+1));out=np.zeros_like(base)
   for k in range(1,11):
    lines=np.zeros_like(base,bool);lines[::step]=masks[k-1][::step];out[ndimage.binary_dilation(lines,structure=disk)]=k
   m=metrics(base,out)
   print(mode,'er',er,'step',step,'metrics',tuple(round(x,4) for x in m),flush=True)
